def hydrate_time(nanoseconds, tz=None):
    """ Hydrator for `Time` and `LocalTime` values.

    :param nanoseconds:
    :param tz:
    :return: Time
    """
    try:
        seconds, nanoseconds = divmod(nanoseconds, 1_000_000_000)
        date_time = datetime.datetime(1970, 1, 1) + datetime.timedelta(seconds=seconds)
        if tz is not None:
            return date_time.replace(tzinfo=tz)
        return date_time.replace(nanosecond=nanoseconds)
    except (ValueError, TypeError) as e:
        raise ValueError(f"Invalid nanoseconds value: {e}")

