def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""

    # Remove any possible BOM or whitespace at start/end
    if not s:
        return ()
    s = s.strip()

    # Strip everything after a "v" if present until the end? 
    # Actually let's just split by dot and other separators. 
    # "poor man's" suggests we just try to find the latest numbers.

    # Remove leading 'v' or 'V' if present
    if s.startswith(('v', 'V')):
        s = s[1:]

    # Split by '.' and also by '-' ' ' etc?
    # The input might be "1.2.3-rc1"
    # We want to compare "1.2.3"

    # For comparison purposes, we likely want to break it down into numeric components.
    # Simple approach: split by '.', then for each part, extract the leading integer.

    parts = s.split('.')
    out = []
    for part in parts:
        # Extract leading digits
        num_str = ''
        for ch in part:
            if ch.isdigit():
                num_str += ch
            else:
                if num_str:
                    break
                else:
                    # If no digit was found, we might want to stop parsing this part
                    # or continue to next char? Usually version parts look like "12" or "2beta".
                    if ch != ' ':  # Allow space? No, just break on non-digit
                         break
                    else:
                         continue
        if num_str:
            try:
                out.append(int(num_str))
            except ValueError:
                out.append(0)
        else:
            # If no digits found in this part (e.g., "" from "1.."), treat as 0?
            # Or stop parsing? 
            # Standard versions don't have empty parts usually.
            out.append(0)

    return tuple(out)

