def lru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm.

    """
    if maxsize == 0:
        return lambda f: _remove_dead_weakref(f)
    if maxsize is None:
        return _caching_decorator(_HashedSeqLRUCache(maxsize))

    def _hashable(args, kwds, typed):
        if kwds:
            return _make_key(args, kwds, typed)
        elif len(args) > 1:
            return _make_key(args, (), typed)
        elif args:
            return hash(args)
        else:
            _none_key = b'\x00'
            return _none_key

    class _Link:
        __slots__ = ('prev', 'next', 'key', 'result')
        def __init__(self, prev, next, key, result):
            self.prev = prev
            self.next = next
            self.key = key
            self.result = result

    def _caching_decorator(user_function, cache):
        @functools.wraps(user_function)
        def wrapper(*args, **kwargs):
            if root is None:
                return user_function(*args, **kwargs)

            k = _hashable(args, kwargs, typed)
            try:
                link = cache[k]
            except KeyError:
                pass
            else:
                p = link.prev
                n = link.next
                p.next = n
                n.prev = p
                root.next = link
                link.prev = root
                link.next = root.prev
                root.prev = link
                hit_count += 1
                return link.result

            miss_count += 1
            # If we're at the maxsize, evict the least recently used
            if len(cache) >= maxsize:
                oldest = root.next
                del cache[oldest.key]
                p = oldest.prev
                n = oldest.next
                p.next = n
                n.prev = p

            result = user_function(*args, **kwargs)
            if root is None:
                root = _Link(None, None, k, result)
                root.prev = root
                root.next = root
            else:
                new_link = _Link(root.prev, root, k, result)
                root.prev.next = new_link
                root.prev = new_link
            cache[k] = new_link
            return result

        wrapper.cache_info = None
        wrapper.cache_clear = None
        return wrapper

