def extostr(cls, e, max_level=30, max_path_level=5):
        """
        Format an exception.
        :param e: Any exception instance.
        :type e: Exception
        :param max_level: Maximum call stack level (default 30)
        :type max_level: int
        :param max_path_level: Maximum path level (default 5)
        :return The exception readable string
        :rtype str
        """
        if not isinstance(e, Exception) and not isinstance(e, type):
            raise ValueError("The provided object is neither an Exception nor an Exception type")

        if isinstance(e, type):
            exception_instance = e()
        else:
            exception_instance = e

        # Get the traceback
        tb = exception_instance.__traceback__
        if tb is None:
            try:
                raise exception_instance
            except Exception as ex:
                tb = ex.__traceback__

        try:
            tb_steps = inspect.getinnerframes(tb)
        except Exception:
            tb_steps = []

        # Take only the last max_level steps
        if len(tb_steps) > max_level:
            tb_steps = tb_steps[-max_level:]

        # Format path
        def format_path(path):
            parts = path.split(os.sep)
            if len(parts) > max_path_level:
                return os.sep.join(['...'] + parts[-max_path_level:])
            return path

        lines = [f"{type(exception_instance).__name__}: {exception_instance}"]

        if tb_steps:
            lines.append("Traceback (most recent call last):")
            for filename, lineno, func_name, code_line in tb_steps:
                formatted_path = format_path(filename)
                lines.append(f'  File "{formatted_path}", line {lineno}, in {func_name}')
                if code_line:
                    lines.append(f"    {code_line}")

        return '\n'.join(lines)

