def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    if not classes:
        return []

    minbases = []
    for base in classes:
        # Check if `base` is already covered by any class in `minbases`
        covered = False
        for existing in minbases:
            if issubclass(base, existing):
                covered = True
                break
        if not covered:
            # Remove any classes in `minbases` that are subclasses of `base`
            # This ensures we keep the most specific ordering? Actually, the goal is minimum.
            # If `base` is a base of `existing`, we should remove `existing`.
            new_minbases = []
            for existing in minbases:
                if not issubclass(existing, base):
                    new_minbases.append(existing)
                # else: existing is a subclass of base, so base covers existing. Remove existing.
            minbases = new_minbases
            minbases.append(base)
    return minbases

