def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but indivial interfaces or implements specs will be expanded.
    """

    if output is None:
        output = []

    cls = sequence.__class__
    # Don't expand a class with __bases__ containing Broken
    if Broken in getattr(sequence, '__bases__', ()):
        return [sequence]

    # If it's an InterfaceClass or Implements, just add it
    if InterfaceClass in cls.__mro__ or Implements in cls.__mro__:
        output.append(sequence)
    else:
        # otherwise, it's a sequence, so expand it
        for v in sequence:
            _normalizeargs(v, output)

    return output

