def reset(self):
    """Reset the histogram.

    Current context is reset to an empty dict.
    Bins are reinitialized with the *initial_value*
    or with *make_bins()* (depending on the initialization).
    """
    # Reset the context to an empty dict
    self.context = {}

    # Reinitialize bins
    if hasattr(self, 'initial_value') and self.initial_value is not None:
        # If initial_value is defined, use it to reinitialize bins
        for key in self.bins.keys():
            self.bins[key] = self.initial_value
    else:
        # Otherwise, call make_bins() to reinitialize
        self.make_bins()

