def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    if not hasattr(inventory, 'state') or not hasattr(inventory.state, 'versioned'):
        return {}
    version_map = {}
    logical_paths = set()
    for vp in inventory.state.virtual_paths:
        if vp in logical_paths:
            continue
        logical_paths.add(vp)
        content_files = []
        version_exists = True
        current_version = version
        while current_version:
            if current_version not in inventory.versioned:
                version_exists = False
                break
            matches = inventory.versioned[current_version].logical_to_physical.get(vp, [])
            if matches:
                for content_file in matches:
                    if content_file not in content_files:
                        content_files.append(content_file)
                break
            elif not matches and current_version == version:
                break
            current_version = inventory.versioned[current_version].parent_version
        if version_exists and content_files:
            version_map[vp] = set(content_files)
    return version_map

