                    for k in range(len(new_args)):
                        if j == k:
                            continue
                        a = new_args[j]
                        b = new_args[k]
                        if isinstance(b, And) and a in b.args:
                            # A | (A & B) = A
                            del new_args[k]
                            simplified = True
                            break
                        # Negative absorption: A | (~A & B) = A | B
                        if isinstance(b, And) and len(b.args) == 2:
                            args_b = list(b.args)
                            for ab in args_b:
                                if isinstance(ab, Not) and (ab.args[0] is a or (hasattr(a, 'equals') and ab.args[0].equals(a))):
