                                    if other_b:
                                        c = other_b[0]
                                        new_args[j] = a
                                        new_args[k] = Or(a, c)
                                        simplified = True
                                        break
                            if simplified:
                                break
                    if simplified:
                        break
            if len(new_args) == 0:
                result[i] = 0
            elif len(new_args) == 1:
                result[i] = new_args[0]
            else:
                result[i] = Or(*new_args)
        i += 1
    return result

