def get_versions():
    """Get version information or return default if unable to do so."""
    import os
    import re

    default_version = "unknown"
    try:
        # Attempt to get version from environment variable
        version = os.environ.get("VERSION", None)
        if version:
            return version

        # Attempt to read version from a file (e.g., VERSION or version.txt)
        for filename in ["VERSION", "version.txt", "_version.py"]:
            version_file = os.path.join(os.path.dirname(__file__), filename)
            if os.path.exists(version_file):
                with open(version_file, "r") as f:
                    content = f.read().strip()
                    if filename in ("VERSION", "version.txt"):
                        return content if content else default_version
                    else:
                        match = re.search(r"__version__\s*=\s*['\"](.+?)['\"]", content)
                        if match:
                            return match.group(1)
    except Exception:
        pass

    return default_version

