def addignored(ignored):
    """Use the git command to obtain the file names, turn it into a list, sort the list for only ignored files, return those files as a single string with each filename separated by a comma."""
    try:
        result = subprocess.run(
            ['git', 'ls-files', '--others', '--ignored', '--exclude-standard'],
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
        )
        if result.returncode != 0:
            raise RuntimeError(
                f"Git command failed with return code {result.returncode}: {result.stderr.decode('utf-8', errors='replace')}"
            )
        files = result.stdout.decode('utf-8', errors='replace').splitlines()
        ignored_files = [f for f in files if f in ignored]
        return ','.join(sorted(ignored_files))
    except FileNotFoundError:
        return ""
    except Exception:
        return ""

