def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    if host is None:
        return False

    # Handle hostname strings
    if isinstance(host, str) and host.lower() in ('localhost', '127.0.0.1', '::1'):
        return True

    # Handle tuple (address, port)
    if isinstance(host, tuple):
        if len(host) < 1:
            return False
        ip = host[0]
    elif isinstance(host, int):
        return False
    else:
        ip = host

    # Convert IP to bytes and check if it's in loopback range
    try:
        if isinstance(ip, str):
            addr = ip
        else:
            addr = str(ip)

        # Try to parse and check if it's a loopback address
        packed = socket.inet_aton(addr)
        if packed.startswith(b'\x7f'):  # 127.0.0.0/8
            return True

        # Check IPv6 loopback
        try:
            packed6 = socket.inet_pton(socket.AF_INET6, addr)
            # ::1 is 15 bytes of 0 then 0001
            if packed6 == b'\x00' * 15 + b'\x01':
                return True
        except (OSError, socket.error):
            pass

        return False
    except (OSError, socket.error, UnicodeError, TypeError):
        return False

