def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    if seq is None:
        return None, None

    seq_type = type(seq)

    if isinstance(seq, (list, tuple)):
        sequence = seq
    elif isinstance(seq, (str, bytes)):
        sequence = str(seq)
        seq_type = str
    elif hasattr(seq, '__iter__'):
        sequence = list(seq)
        seq_type = list
    else:
        sequence = str(seq)
        seq_type = str

    if bufsize is not None and not isinstance(bufsize, int):
        bufsize = int(bufsize)
    elif bufsize is not None and bufsize <= 0:
        bufsize = 8192

    return sequence, seq_type

