def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__.

    Args:
        bases: A list or tuple of base classes.
        explicit_mc: An explicit metaclass object returned from __metaclass__

    Returns:
        The determined metaclass.
        Rises exception is there is no metaclass.
    """
    if explicit_mc is not None and not isinstance(explicit_mc, type):
        raise ValueError("Explicit metaclass must be a class or None, got %r" % (explicit_mc,))

    metaclass = None

    if explicit_mc is not None:
        metaclass = explicit_mc

    if bases is not None:
        for base in bases:
            base_mc = type(base)
            if metaclass is None:
                metaclass = base_mc
            else:
                if not issubclass(base_mc, metaclass):
                    raise TypeError("metaclass conflict: the metaclass of a derived class "
                                    "must be a (non-strict) subclass of the metaclasses of all its bases")

    if metaclass is None:
        metaclass = type

    if not isinstance(metaclass, type):
        raise ValueError("Metaclass must be a class, got %r" % (metaclass,))

    return metaclass

