def format_dt(dt):
    """
    Format a datetime in the way that D* nodes expect.
    """
    if dt is None:
        return None
    # Assuming D* nodes expect ISO 8601 format with 'Z' for UTC
    if dt.tzinfo is not None:
        dt = dt.astimezone(datetime.timezone.utc)
    return dt.strftime('%Y-%m-%dT%H:%M:%S.%fZ')

