def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    try:
        parsed = json.loads(document)
        return parsed
    except (json.JSONDecodeError, ValueError):
        pass

    try:
        root = fromstring(document)
        if root.tag != 'XRD' and root.tag != 'xrd':
            return {}
        result = {}
        for link in root.findall('link'):
            rel = link.get('rel')
            url = link.get('template') or link.get('href')
            if rel and url:
                if rel not in result:
                    result[rel] = []
                result[rel].append(url)
        # Convert single-element lists to simple values for compatibility if needed,
        # but the standard structure often keeps lists. However, diaspora code often expects
        # specific structures. Let's look at how the keys are used.
        # Usually, 'diaspora:person' or 'lrdd' or 'hcard' are the keys.
        # If the docs say it returns a dict, we return the structure found.
        # Most webfinger parsers return a dict where keys are 'rel' and values are lists of URLs/objects.
        return result
    except (ParseError, ET.ParseError) as e:
        logger.warning("Failed to parse webfinger document: %s", str(e))
        return {}

