def validate_from_content(cls, spec_content=None):
    """validates that spec (YAML) content has all required fields

    :param spec_content: content of spec file
    :raise IRValidatorException: when mandatory data
    is missing in spec file
    :return: Dictionary with data loaded from a spec (YAML) file
    """
    import yaml
    import json

    if spec_content is None:
        raise IRValidatorException("spec_content must be provided")

    try:
        spec = yaml.safe_load(spec_content)
    except yaml.YAMLError as e:
        raise IRValidatorException(f"YAML parsing error in spec content: {str(e)}")

    if not isinstance(spec, dict):
        raise IRValidatorException("Spec content must be a YAML dictionary")

    required_fields = ['name', 'inputs', 'outputs']

    for field in required_fields:
        if field not in spec:
            raise IRValidatorException(f"Missing required field in spec: {field}")

        if spec[field] is None:
            raise IRValidatorException(f"Empty value provided for required field: {field}")

    return spec

