            if isinstance(args, dict):
                # Check if the condition key exists in args and its value is truthy
                if required_when in args and args[required_when]:
                    condition_met = True
            else:
                # Try to check if args can be iterated or has attribute
                try:
                    if hasattr(args, required_when) and getattr(args, required_when):
                        condition_met = True
                    elif isinstance(args, (list, tuple)):
                        # Fallback: if args is a list, maybe it contains command name?
