def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if extra_vars is None:
        return
    new_vars_dict = vars_dict.copy()
    for extra_var in extra_vars:
        if isinstance(extra_var, str) and "=" in extra_var:
            key, _, value = extra_var.partition("=")
            new_vars_dict[key.strip()] = value.strip()
        else:
            raise ValueError("Invalid extra var format: expected 'key=value' string")
    return new_vars_dict

