def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
       """
    # If the parser does not exist, nothing to do
    if parser_name not in self._parsers:
        return

    parser = self._parsers[parser_name]

    # If the values_dict is None or empty, nothing to do
    if not values_dict:
        return

    # Iterate over the arguments defined in the parser
    # Do not modify the keys, only the values
    for action in parser._actions:
        # Only consider options (those with a dest)
        if action.dest is not None and action.dest in values_dict:
            # Get the type function if defined, otherwise default to str
            # action.type is a callable or None
            if action.type is not None:
                key = action.dest
                value = values_dict[key]
                try:
                    # If the value is a list, convert each element
                    if isinstance(value, list):
                        values_dict[key] = [action.type(v) for v in value]
                    else:
                        values_dict[key] = action.type(value)
                except (TypeError, ValueError):
                    # If conversion fails, keep the original string value
                    pass

