def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import yaml
    import os

    spec_file = os.path.join(plugin_dir, 'plugin.yaml')
    if not os.path.exists(spec_file):
        spec_file = os.path.join(plugin_dir, 'plugin.json')
        if os.path.exists(spec_file):
            import json
            with open(spec_file, 'r') as f:
                plugin_spec = json.load(f)
        else:
            raise ValueError("No plugin spec file found in {:s}".format(plugin_dir))
    else:
        with open(spec_file, 'r') as f:
            plugin_spec = yaml.safe_load(f)

    def flatten_dict(nested_dict, prefix='', separator='_'):
        flat_dict = {}
        for key, value in nested_dict.items():
            new_key = prefix + separator + str(key) if prefix else str(key)
            if isinstance(value, dict):
                flat_dict.update(flatten_dict(value, new_key, separator))
            elif isinstance(value, list):
                for i, item in enumerate(value):
                    new_key_with_index = new_key + separator + str(i)
                    if isinstance(item, dict):
                        flat_dict.update(flatten_dict(item, new_key_with_index, separator))
                    else:
                        flat_dict[new_key_with_index] = item
            else:
                flat_dict[new_key] = str(value) if value is not None else ''
        return flat_dict

    return flatten_dict(plugin_spec)

